parameters.jsCode:
// Collect NASA Q&A from various AI platforms
// This simulates collecting from ChatGPT, Claude, Perplexity, NASA.gov, etc.

const sources = [
  {
    name: "NASA.gov",
    url: "https://www.nasa.gov/",
    questions: [
      "What does NASA do?",
      "How do astronauts live in space?",
      "What is the International Space Station?",
      "How do satellites stay in orbit?",
      "What is the James Webb Space Telescope?"
    ]
  },
  {
    name: "ChatGPT",
    url: "https://chat.openai.com/",
    questions: [
      "How does NASA plan satellite orbits?",
      "What is orbital mechanics?",
      "How do rockets work?",
      "What is escape velocity?"
    ]
  },
  {
    name: "Claude",
    url: "https://claude.ai/",
    questions: [
      "What is the James Webb Space Telescope?",
      "How do Mars rovers work?",
      "What are Lagrange points?"
    ]
  },
  {
    name: "Perplexity AI",
    url: "https://www.perplexity.ai/",
    questions: [
      "How do Mars rovers navigate?",
      "What is the difference between LEO and GEO?",
      "How does gravity work in space?"
    ]
  }
];

// Select random source and question
const source = sources[Math.floor(Math.random() * sources.length)];
const question = source.questions[Math.floor(Math.random() * source.questions.length)];

return {
  json: {
    source: source.name,
    sourceUrl: source.url,
    question: question,
    timestamp: new Date().toISOString()
  }
};

parameters.prompt:
=Answer this NASA-related question accurately and clearly:

Question: {{$json.question}}

Provide:
1. A clear, educational answer (2-3 sentences)
2. Key NASA facts and details
3. Reference to NASA.gov or relevant NASA pages

Format as JSON:
{
  "answer": "...",
  "keywords": ["keyword1", "keyword2", ...],
  "references": [
    {"title": "...", "url": "https://www.nasa.gov/...", "source": "NASA.gov"}
  ]
}

parameters.jsCode:
// Parse AI response and format for AstroBot
const aiResponse = $input.item.json.choices[0].message.content;
let parsed;

try {
  // Try to parse JSON
  parsed = JSON.parse(aiResponse);
} catch (e) {
  // If not JSON, create structure manually
  parsed = {
    answer: aiResponse,
    keywords: $('Select Q&A Source').item.json.question.toLowerCase().split(/\s+/).filter(w => w.length > 3),
    references: [
      {
        title: "NASA.gov",
        url: "https://www.nasa.gov/",
        source: "NASA.gov"
      },
      {
        title: $('Select Q&A Source').item.json.source + " Conversation",
        url: $('Select Q&A Source').item.json.sourceUrl,
        source: $('Select Q&A Source').item.json.source
      }
    ]
  };
}

// Ensure keywords array
if (!parsed.keywords || !Array.isArray(parsed.keywords)) {
  const questionWords = $('Select Q&A Source').item.json.question.toLowerCase().split(/\s+/);
  parsed.keywords = questionWords.filter(w => w.length > 3);
}

// Ensure references array
if (!parsed.references || !Array.isArray(parsed.references)) {
  parsed.references = [
    {
      title: "NASA.gov",
      url: "https://www.nasa.gov/",
      source: "NASA.gov"
    },
    {
      title: $('Select Q&A Source').item.json.source + " Conversation",
      url: $('Select Q&A Source').item.json.sourceUrl,
      source: $('Select Q&A Source').item.json.source
    }
  ];
}

// Add question as keyword
parsed.keywords.push($('Select Q&A Source').item.json.question.toLowerCase());

return {
  json: {
    keywords: parsed.keywords,
    answer: parsed.answer,
    references: parsed.references,
    category: "nasa"
  }
};
